import { getSession } from '@/app/lib/auth'
import { forbidden } from 'next/navigation'

export default async function AdminPage() {
  const session = await getSession()

  // Check if the user is authenticated and has the 'admin' role
  if (!session || session.role !== 'admin') {
    forbidden()
  }

  // Render the admin page for authorized users
  return (
    <main style={{
      padding: '40px',
      maxWidth: '1200px',
      margin: '0 auto',
      fontFamily: 'system-ui, -apple-system, sans-serif'
    }}>
      <h1 style={{ fontSize: '2.5rem', marginBottom: '20px' }}>Admin Dashboard</h1>
      <p style={{ fontSize: '1.125rem', color: '#64748b', marginBottom: '30px' }}>
        Welcome, {session.name}!
      </p>
      <div style={{
        padding: '30px',
        backgroundColor: '#f8fafc',
        borderRadius: '8px',
        border: '1px solid #e2e8f0'
      }}>
        <h2 style={{ fontSize: '1.5rem', marginBottom: '15px' }}>Admin Panel</h2>
        <p style={{ color: '#475569' }}>
          This is a protected admin area. Only users with the "admin" role can access this page.
        </p>
        <div style={{ marginTop: '20px' }}>
          <p><strong>User ID:</strong> {session.userId}</p>
          <p><strong>Role:</strong> {session.role}</p>
        </div>
      </div>
    </main>
  )
}

